def all_suffixes(string: str) -> List[str]:
    """ Return list of all suffixes from longest to shortest of the input string
    >>> all_suffixes('abc')
    ['abc', 'bc', 'c']
    """
    return [string[i:] for i in range(len(string))]


def longest_common_prefix(s1: str, s2: str) -> str:
    """ Return the longest common prefix of two strings
    >>> longest_common_prefix('abcde', 'abcxy')
    'abc'
    """
    min_length = min(len(s1), len(s2))
    for i in range(min_length):
        if s1[i] != s2[i]:
            return s1[:i]
    return s1[:min_length]


def longest_common_suffix(s1: str, s2: str) -> str:
    """ Return the longest common suffix of two strings
    >>> longest_common_suffix('abcde', 'xyzde')
    'de'
    """
    min_length = min(len(s1), len(s2))
    for i in range(1, min_length + 1):
        if s1[-i] != s2[-i]:
            return s1[-i+1:]
    return s1[-min_length:]

def longest_common_substring(s1: str, s2: str) -> str:
    """ Return the longest common substring of two strings
    >>> longest_common_substring('abcde', 'cdefg')
    'cde'
    """
    m, n = len(s1), len(s2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    longest_length = 0
    end_index_s1 = 0

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
                if dp[i][j] > longest_length:
                    longest_length = dp[i][j]
                    end_index_s1 = i

    start_index_s1 = end_index_s1 - longest_length
    return s1[start_index_s1:end_index_s1]


def longest_common_subsequence(s1: str, s2: str) -> str:
    """ Return the longest common subsequence of two strings
    >>> longest_common_subsequence('abcde', 'ace')
    'ace'
    """
    m, n = len(s1), len(s2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # Reconstruct the longest common subsequence from dp table
    lcs = []
    i, j = m, n
    while i > 0 and j > 0:
        if s1[i - 1] == s2[j - 1]:
            lcs.append(s1[i - 1])
            i -= 1
            j -= 1
        elif dp[i - 1][j] > dp[i][j - 1]:
            i -= 1
        else:
            j -= 1

    return ''.join(reversed(lcs))


