    >>> fib_iter(1)
    1
    >>> fib_iter(8)
    21
    """
    if n == 0:
        return 0
    elif n == 1:
        return 1
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b


