def minPath(grid, k):
    def dfs(x, y, steps, path, best_path):
        if steps == k:
            return path

        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < len(grid) and 0 <= ny < len(grid):
                new_path = path + [grid[nx][ny]]
                if new_path < best_path:
                    candidate = dfs(nx, ny, steps + 1, new_path, best_path)
                    if candidate < best_path:
