    min_lex_path = [float('inf')] * k
    for i in range(len(grid)):
        for j in range(len(grid)):
            path = dfs(i, j, 1, [grid[i][j]], min_lex_path)
            if path < min_lex_path:
                min_lex_path = path
    return min_lex_path

